export function encapsMananaDe(iso: string): EncapsMananaDia | null { return M[k(iso)] ?? null; }
/** Las 7 franjas de la mañana ENCAPS (07:15-12:00; el mié 30-dic, simulacro de cierre) · [] si no hay. */
